   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_created_at",
   "type": "string",
   "required": false,
   "description": "Maximum created_at datetime to filter transactions in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "min_like_count",
   "type": "integer",
   "required": false,
   "description": "Minimum like count to filter transactions.",
   "default": 0,
   "constraints": []
  },
  {
   "name": "max_like_count",
   "type": "integer",
   "required": false,
   "description": "Maximum like count to filter transactions.",
   "default": 9223372036854775807,
   "constraints": []
